func testAppUserToManyRemoveOpLockedByUserProjects(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a AppUser
	var b, c, d, e Project

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, appUserDBTypes, false, strmangle.SetComplement(appUserPrimaryKeyColumns, appUserColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Project{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, projectDBTypes, false, strmangle.SetComplement(projectPrimaryKeyColumns, projectColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddLockedByUserProjects(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.LockedByUserProjects().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveLockedByUserProjects(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.LockedByUserProjects().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.LockedByUserID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.LockedByUserID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.LockedByUser != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.LockedByUser != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.LockedByUser != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.LockedByUser != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.LockedByUserProjects) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.LockedByUserProjects[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.LockedByUserProjects[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

